mapper.select:
select
a.rule_id,
a.plan_id,
a.rule_name,
a.rule_type,
a.rule_content,
a.rule_delay,
a.description,
a.input_param,
a.create_time,
a.update_time
from t_cfg_union_rule a
where 1 = 1
 and a.rule_id = #{ruleId, jdbcType=BIGINT}
 and a.plan_id = #{planId, jdbcType=BIGINT}
 and a.rule_name = #{ruleName, jdbcType=VARCHAR}
 and a.rule_type = #{ruleType, jdbcType=VARCHAR}
 and a.rule_content = #{ruleContent, jdbcType=VARCHAR}
 and a.rule_delay = #{ruleDelay, jdbcType=INTEGER}
 and a.description = #{description, jdbcType=VARCHAR}
 and a.input_param = #{inputParam, jdbcType=VARCHAR}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}

select
a.rule_id,
a.plan_id,
a.rule_name,
a.rule_type,
a.rule_content,
a.rule_delay,
a.description,
a.input_param,
a.create_time,
a.update_time,
b.plan_name
from t_cfg_union_rule a
left join t_cruise_plan b on a.plan_id = b.plan_id
where 1 = 1
 and a.rule_id = #{ruleId, jdbcType=BIGINT}
 and a.plan_id = #{planId, jdbcType=BIGINT}
 and a.rule_name = #{ruleName, jdbcType=VARCHAR}
 and a.rule_type = #{ruleType, jdbcType=VARCHAR}
 and a.rule_content = #{ruleContent, jdbcType=VARCHAR}
 and a.rule_delay = #{ruleDelay, jdbcType=INTEGER}
 and a.description = #{description, jdbcType=VARCHAR}
 and a.input_param = #{inputParam, jdbcType=VARCHAR}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
 order by a.rule_id desc

